<div class="patient-page-heading"><div><span class="eyebrow text-secondary">CONTROL DE ACCESO</span><h1>Usuarios</h1><p class="text-secondary mb-0">Consulta cuentas y administra sus datos permitidos.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="/usuarios/roles">Ver roles y permisos</a><a class="btn btn-clinic" href="/usuarios/nuevo">+ Crear usuario</a></div></div>
<section class="patient-card"><div class="patient-list-toolbar"><div><strong><?= $escape($result['total']) ?></strong> cuentas<span class="live-label">Consulta de PostgreSQL · hashes nunca mostrados</span></div>
<form action="/usuarios" method="get" class="patient-search" role="search"><label class="visually-hidden" for="q">Buscar</label><input class="form-control" id="q" name="q" maxlength="200" value="<?= $escape($search) ?>" placeholder="Usuario o correo"><select class="form-select" name="rol" aria-label="Filtrar por rol"><option value="">Todos los roles</option><?php foreach($roles as $item): ?><option value="<?= $escape($item['id_rol']) ?>" <?= $role===(int)$item['id_rol']?'selected':'' ?>><?= $escape($item['nombre']) ?></option><?php endforeach; ?></select><select class="form-select" name="estado" aria-label="Filtrar por estado"><option value="">Todos los estados</option><option value="activo" <?= $status==='activo'?'selected':'' ?>>Activo</option><option value="inactivo" <?= $status==='inactivo'?'selected':'' ?>>Inactivo</option></select><button class="btn btn-clinic" type="submit">Filtrar</button><?php if($search!==''||$role!==null||$status!==null): ?><a class="btn btn-outline-secondary" href="/usuarios">Limpiar</a><?php endif; ?></form></div>
<?php if(!$result['items']): ?><div class="patient-empty"><h2 class="h5">No hay cuentas para mostrar</h2><p class="text-secondary">Ajusta los filtros e inténtalo de nuevo.</p></div><?php else: ?><div class="table-responsive"><table class="table patient-table align-middle mb-0"><caption class="visually-hidden">Listado de usuarios</caption><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($result['items'] as $account): ?><tr><td><strong><?= $escape($account['nombre_usuario']) ?></strong></td><td><?= $escape($account['correo_acceso']) ?></td><td><?= $escape($account['rol']) ?></td><td><span class="status-chip <?= $account['estado']==='activo'?'is-active':'is-inactive' ?>"><?= $escape(ucfirst($account['estado'])) ?></span></td><td><div class="patient-row-actions"><a href="/usuarios/detalle?id=<?= $escape($account['id_usuario']) ?>">Detalle</a><a href="/usuarios/editar?id=<?= $escape($account['id_usuario']) ?>">Editar</a></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="patient-pagination"><span><?= $result['total'] ? 'Mostrando '.(($result['page']-1)*10+1).'–'.min($result['total'],$result['page']*10).' de '.$result['total'] : '0 resultados' ?></span><nav aria-label="Páginas"><ul class="pagination mb-0"><?php $url=static fn(int $p):string=>'/usuarios?'.http_build_query(['q'=>$search,'rol'=>$role,'estado'=>$status,'pagina'=>$p]); ?><?php if($result['page']>1): ?><li class="page-item"><a class="page-link" href="<?= $escape($url($result['page']-1)) ?>">Anterior</a></li><?php endif; ?><?php for($p=max(1,$result['page']-2);$p<=min($result['pages'],$result['page']+2);$p++): ?><li class="page-item <?= $p===$result['page']?'active':'' ?>"><a class="page-link" href="<?= $escape($url($p)) ?>"><?= $p ?></a></li><?php endfor; ?><?php if($result['page']<$result['pages']): ?><li class="page-item"><a class="page-link" href="<?= $escape($url($result['page']+1)) ?>">Siguiente</a></li><?php endif; ?></ul></nav></div></section>
